  Multiport_Switch_offset_out1 <= client_fifo1_offset_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#0#, 3) ELSE
      client_fifo2_offset_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#1#, 3) ELSE
      client_fifo3_offset_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#2#, 3) ELSE
      client_fifo4_offset_unsigned WHEN req_counter_out_unsigned = to_unsigned(16#3#, 3) ELSE
