  BEGIN
    IF req_counter_out_unsigned = to_unsigned(16#0#, 3) THEN 
      Multiport_Switch_wrData_out1 <= DataTypeConv1_OutData;
    ELSIF req_counter_out_unsigned = to_unsigned(16#1#, 3) THEN 
      Multiport_Switch_wrData_out1 <= DataTypeConv3_OutData;
    ELSIF req_counter_out_unsigned = to_unsigned(16#2#, 3) THEN 
      Multiport_Switch_wrData_out1 <= DataTypeConv5_OutData;
    ELSIF req_counter_out_unsigned = to_unsigned(16#3#, 3) THEN 
      Multiport_Switch_wrData_out1 <= DataTypeConv7_OutData;
    ELSE 
      Multiport_Switch_wrData_out1 <= DataTypeConv11_OutData;
    END IF;
  END PROCESS Multiport_Switch_wrData_output;


